@namespace sv_6d3535725b4f400e81fef8180acb677d.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application steps">
    <ol>
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i;
            var css = step == CurrentStep ? "active"
                    : step < CurrentStep ? "completed"
                    : "upcoming";

            <li class="step @css"
                role="button"
                @onclick="() => GoToStep(step)"
                tabindex="@(step < CurrentStep ? 0 : -1)"
                aria-current="@(step == CurrentStep ? "step" : null)">
                <span class="step-number">
                    @if (step < CurrentStep)
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        @(step + 1)
                    }
                </span>
                <span class="step-label">@StepNames[step]</span>
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames =
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private async Task GoToStep(int step)
    {
        if (step < CurrentStep)
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

@namespace sv_6d3535725b4f400e81fef8180acb677d.Components.Pages.Apply

<div class="step-content">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" />
        @if (_errors.ContainsKey("FullName"))
        {
            <span class="field-error">@_errors["FullName"]</span>
        }
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" @bind="Email" @bind:event="oninput" />
        @if (_errors.ContainsKey("Email"))
        {
            <span class="field-error">@_errors["Email"]</span>
        }
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" />
        @if (_errors.ContainsKey("Phone"))
        {
            <span class="field-error">@_errors["Phone"]</span>
        }
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <textarea id="address" @bind="Address" @bind:event="oninput" rows="3"></textarea>
        @if (_errors.ContainsKey("Address"))
        {
            <span class="field-error">@_errors["Address"]</span>
        }
    </div>

    @if (_validatingEmail)
    {
        <p class="info-message">Validating email...</p>
    }

    <div class="step-buttons">
        <button class="btn-primary" @onclick="HandleNext" disabled="@_validatingEmail">Next</button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<(string FullName, string Email, string Phone, string Address)> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private Dictionary<string, string> _errors = new();
    private bool _validatingEmail;

    private async Task HandleNext()
    {
        _errors.Clear();

        if (string.IsNullOrWhiteSpace(FullName))
            _errors["FullName"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(Email))
            _errors["Email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(Phone))
            _errors["Phone"] = "Phone is required.";
        if (string.IsNullOrWhiteSpace(Address))
            _errors["Address"] = "Address is required.";

        if (_errors.Count > 0) return;

        if (ValidateEmail is not null)
        {
            _validatingEmail = true;
            StateHasChanged();

            var isValid = await ValidateEmail(Email);
            _validatingEmail = false;

            if (!isValid)
            {
                _errors["Email"] = "Please enter a valid email address.";
                return;
            }
        }

        await OnNext.InvokeAsync((FullName, Email, Phone, Address));
    }
}

@namespace sv_6d3535725b4f400e81fef8180acb677d.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn-danger-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company"
               @onchange="e => Update(Entry with { Company = (string?)e.Value ?? "" })" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title"
               @onchange="e => Update(Entry with { Title = (string?)e.Value ?? "" })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => Update(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? "")"
                   disabled="@_isCurrent"
                   @onchange="e => Update(Entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" />
        </div>
    </div>

    <div class="form-group checkbox-group">
        <label>
            <input type="checkbox" checked="@_isCurrent" @onchange="ToggleCurrent" />
            I currently work here
        </label>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description"
                  @onchange="e => Update(Entry with { Description = (string?)e.Value ?? "" })"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool _isCurrent;

    protected override void OnParametersSet()
    {
        _isCurrent = Entry.EndDate is null && Entry.StartDate != default;
    }

    private void ToggleCurrent(ChangeEventArgs e)
    {
        _isCurrent = (bool)(e.Value ?? false);
        if (_isCurrent)
        {
            Update(Entry with { EndDate = null });
        }
    }

    private async void Update(WorkEntryModel updated)
    {
        await OnEntryChanged.InvokeAsync(updated);
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public string Description { get; set; } = "";
    }
}

@namespace sv_6d3535725b4f400e81fef8180acb677d.Components.Pages.Apply

<div class="step-content">
    <h2>Work History</h2>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="index"
                       CanRemove="@(Entries.Count > 1)"
                       OnEntryChanged="e => UpdateEntry(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (_error is not null)
    {
        <p class="field-error">@_error</p>
    }

    <div class="step-buttons">
        <button class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryForm.WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<WorkEntryForm.WorkEntryModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? _error;

    protected override void OnInitialized()
    {
        if (Entries.Count == 0)
            Entries.Add(new WorkEntryForm.WorkEntryModel());
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntryForm.WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private void UpdateEntry(int index, WorkEntryForm.WorkEntryModel updated)
    {
        Entries[index] = updated;
    }

    private async Task HandleNext()
    {
        _error = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                _error = "Each position must have a company name and job title.";
                return;
            }
        }

        await OnNext.InvokeAsync(Entries);
    }
}

@namespace sv_6d3535725b4f400e81fef8180acb677d.Components.Pages.Apply

<div class="step-content">
    <h2>References</h2>
    <p class="hint">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < _references.Count; i++)
    {
        var index = i;
        <div class="reference-entry">
            <div class="entry-header">
                <h4>Reference @(index + 1)</h4>
                @if (_references.Count > 2)
                {
                    <button class="btn-danger-sm" @onclick="() => RemoveReference(index)">Remove</button>
                }
            </div>

            <div class="form-group">
                <label>Name *</label>
                <input type="text" value="@_references[index].Name"
                       @onchange="e => UpdateRef(index, _references[index] with { Name = (string?)e.Value ?? "" })" />
            </div>

            <div class="form-group">
                <label>Relationship *</label>
                <input type="text" value="@_references[index].Relationship"
                       @onchange="e => UpdateRef(index, _references[index] with { Relationship = (string?)e.Value ?? "" })" />
            </div>

            <div class="form-row">
                <div class="form-group">
                    <label>Email *</label>
                    <input type="email" value="@_references[index].Email"
                           @onchange="e => UpdateRef(index, _references[index] with { Email = (string?)e.Value ?? "" })" />
                </div>

                <div class="form-group">
                    <label>Phone *</label>
                    <input type="tel" value="@_references[index].Phone"
                           @onchange="e => UpdateRef(index, _references[index] with { Phone = (string?)e.Value ?? "" })" />
                </div>
            </div>
        </div>
    }

    @if (_references.Count < 3)
    {
        <button class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (_error is not null)
    {
        <p class="field-error">@_error</p>
    }

    <div class="step-buttons">
        <button class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<ReferenceModel> _references = new();
    private string? _error;

    protected override void OnParametersSet()
    {
        if (_references.Count == 0)
        {
            _references = References.Count > 0
                ? References.ToList()
                : new List<ReferenceModel> { new(), new() };
        }
    }

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 2)
            _references.RemoveAt(index);
    }

    private void UpdateRef(int index, ReferenceModel updated)
    {
        _references[index] = updated;
    }

    private async Task HandleNext()
