<div class="step-content">
    <h2>References</h2>
    <p class="hint">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < _references.Count; i++)
    {
        var index = i;
        <div class="reference-entry">
            <div class="entry-header">
                <h4>Reference @(index + 1)</h4>
                @if (_references.Count > 2)
                {
                    <button class="btn-danger-sm" @onclick="() => RemoveReference(index)">Remove</button>
                }
            </div>

            <div class="form-group">
                <label>Name *</label>
                <input type="text" value="@_references[index].Name"
                       @onchange="e => UpdateRef(index, _references[index] with { Name = (string?)e.Value ?? "" })" />
            </div>

            <div class="form-group">
                <label>Relationship *</label>
                <input type="text" value="@_references[index].Relationship"
                       @onchange="e => UpdateRef(index, _references[index] with { Relationship = (string?)e.Value ?? "" })" />
            </div>

            <div class="form-row">
                <div class="form-group">
                    <label>Email *</label>
                    <input type="email" value="@_references[index].Email"
                           @onchange="e => UpdateRef(index, _references[index] with { Email = (string?)e.Value ?? "" })" />
                </div>

                <div class="form-group">
                    <label>Phone *</label>
                    <input type="tel" value="@_references[index].Phone"
                           @onchange="e => UpdateRef(index, _references[index] with { Phone = (string?)e.Value ?? "" })" />
                </div>
            </div>
        </div>
    }

    @if (_references.Count < 3)
    {
        <button class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (_error is not null)
    {
        <p class="field-error">@_error</p>
    }

    <div class="step-buttons">
        <button class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<ReferenceModel> _references = new();
    private string? _error;

    protected override void OnParametersSet()
    {
        if (_references.Count == 0)
        {
            _references = References.Count > 0
                ? References.ToList()
                : new List<ReferenceModel> { new(), new() };
        }
    }

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 2)
            _references.RemoveAt(index);
    }

    private void UpdateRef(int index, ReferenceModel updated)
    {
        _references[index] = updated;
    }

    private async Task HandleNext()
    {
        _error = null;

        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _error = "All reference fields are required.";
                return;
            }
        }

        await OnNext.InvokeAsync(_references);
    }

    public record ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}
