@namespace sv_6d3535725b4f400e81fef8180acb677d.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application steps">
    <ol>
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i;
            var css = step == CurrentStep ? "active"
                    : step < CurrentStep ? "completed"
                    : "upcoming";

            <li class="step @css"
                role="button"
                @onclick="() => GoToStep(step)"
                tabindex="@(step < CurrentStep ? 0 : -1)"
                aria-current="@(step == CurrentStep ? "step" : null)">
                <span class="step-number">
                    @if (step < CurrentStep)
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        @(step + 1)
                    }
                </span>
                <span class="step-label">@StepNames[step]</span>
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames =
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepSelected { get; set; }

    private async Task GoToStep(int step)
    {
        if (step < CurrentStep)
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

