@namespace sv_6d3535725b4f400e81fef8180acb677d.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter</label>
        <textarea id="coverLetter" rows="12" maxlength="2000"
                  @bind="Text" @bind:event="oninput"></textarea>
        <span class="char-count @(Text.Length > 1800 ? "near-limit" : "")">
            @Text.Length / 2000 characters
        </span>
    </div>

    @if (_error is not null)
    {
        <p class="field-error">@_error</p>
    }

    <div class="step-buttons">
        <button class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string Text { get; set; } = "";
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? _error;

    private async Task HandleNext()
    {
        _error = null;

        if (string.IsNullOrWhiteSpace(Text))
        {
            _error = "Please write a cover letter before proceeding.";
            return;
        }

        await OnNext.InvokeAsync(Text);
    }
}

