toolArgs.file_text:
@namespace sv_6d3535725b4f400e81fef8180acb677d.Components.Pages.Apply

<div class="step-content review-step">
    <h2>Review & Submit</h2>
    <p>Please review your application before submitting.</p>

    <section class="review-section">
        <div class="section-header">
            <h3>Personal Information</h3>
            <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
        </div>
        <dl>
            <dt>Full Name</dt><dd>@Personal.FullName</dd>
            <dt>Email</dt><dd>@Personal.Email</dd>
            <dt>Phone</dt><dd>@Personal.Phone</dd>
            <dt>Address</dt><dd>@Personal.Address</dd>
        </dl>
    </section>

    <section class="review-section">
        <div class="section-header">
            <h3>Work History</h3>
            <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
        </div>
        @foreach (var entry in WorkEntries)
        {
            <div class="review-work-entry">
                <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                <br />
                <span class="date-range">
                    @entry.StartDate.ToString("MMM yyyy") –
                    @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                </span>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p class="entry-description">@entry.Description</p>
                }
            </div>
        }
    </section>

    <section class="review-section">
        <div class="section-header">
            <h3>References</h3>
            <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
        </div>
        @foreach (var r in References)
        {
            <div class="review-reference">
                <strong>@r.Name</strong> — @r.Relationship
                <br />
                <span>@r.Email | @r.Phone</span>
            </div>
        }
    </section>

    <section class="review-section">
        <div class="section-header">
            <h3>Cover Letter</h3>
            <button class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
        </div>
        <p class="cover-letter-preview">@CoverLetter</p>
    </section>

    @if (_error is not null)
    {
        <p class="field-error">@_error</p>
    }

    <div class="step-buttons">
        <button class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@_submitting">
            @(_submitting ? "Submitting..." : "Submit Application")
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public (string FullName, string Email, string Phone, string Address) Personal { get; set; }
    [Parameter, EditorRequired] public List<WorkEntryForm.WorkEntryModel> WorkEntries { get; set; } = new();
    [Parameter, EditorRequired] public List<ReferencesStep.ReferenceModel> References { get; set; } = new();
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private bool _submitting;
    private string? _error;

    private async Task HandleSubmit()
    {
        _submitting = true;
        _error = null;
        StateHasChanged();

        try
        {
            await OnSubmit.InvokeAsync();
        }
        catch (Exception ex)
        {
            _error = $"Submission failed: {ex.Message}";
            _submitting = false;
        }
    }
}

