<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    @if (_submitted)
    {
        <div class="confirmation">
            <div class="confirmation-icon">&#10003;</div>
            <h2>Application Submitted!</h2>
            <p>Your application has been received. Your application ID is:</p>
            <p class="application-id">#@_applicationId</p>
            <p>Please save this number for your records.</p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="_currentStep" OnStepSelected="GoToStep" />

        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@_fullName" Email="@_email" Phone="@_phone" Address="@_address"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="HandlePersonalInfoNext" />
                break;

            case 1:
                <WorkHistoryStep Entries="_workEntries" OnNext="HandleWorkHistoryNext" OnBack="GoBack" />
                break;

            case 2:
                <ReferencesStep References="_references" OnNext="HandleReferencesNext" OnBack="GoBack" />
                break;

            case 3:
                <CoverLetterStep Text="@_coverLetter" OnNext="HandleCoverLetterNext" OnBack="GoBack" />
                break;

            case 4:
                <ReviewStep Personal="(_fullName, _email, _phone, _address)"
                            WorkEntries="_workEntries"
                            References="_references"
                            CoverLetter="@_coverLetter"
                            OnEditSection="GoToStep"
                            OnSubmit="HandleSubmit"
                            OnBack="GoBack" />
                break;
        }
    }
</div>

@code {
    private int _currentStep;
    private bool _submitted;
    private int _applicationId;

    // Step 1 data
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 data
    private List<WorkEntryForm.WorkEntryModel> _workEntries = new() { new() };

    // Step 3 data
    private List<ReferencesStep.ReferenceModel> _references = new();

    // Step 4 data
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private void GoBack()
    {
        if (_currentStep > 0)
            _currentStep--;
    }

    private void HandlePersonalInfoNext((string FullName, string Email, string Phone, string Address) data)
    {
        _fullName = data.FullName;
        _email = data.Email;
        _phone = data.Phone;
        _address = data.Address;
        _currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        _workEntries = entries;
        _currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> references)
    {
        _references = references;
        _currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        _coverLetter = text;
        _currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        var workHistory = new WorkHistory(
            _workEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()
        );

        var references = _references
            .Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone))
            .ToList();

        var application = new JobApplication(
            new PersonalInfo(_fullName, _email, _phone, _address),
            workHistory,
            references,
            _coverLetter
        );

        _applicationId = await ApplicationService.SubmitApplicationAsync(application);
        _submitted = true;
    }
}

.application-form {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1.5rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator ol {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem 0;
    justify-content: space-between;
}

.step-indicator .step {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    position: relative;
    cursor: default;
}

.step-indicator .step.completed {
    cursor: pointer;
}

.step-indicator .step-number {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
    border: 2px solid #ddd;
    background: #fff;
    color: #999;
    transition: all 0.2s ease;
}

.step-indicator .step.active .step-number {
    border-color: #4361ee;
    background: #4361ee;
    color: #fff;
}

.step-indicator .step.completed .step-number {
    border-color: #2ec4b6;
    background: #2ec4b6;
    color: #fff;
}

.step-indicator .step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #999;
}

.step-indicator .step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step-indicator .step.completed .step-label {
    color: #2ec4b6;
}

.checkmark {
    font-size: 1rem;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #e8e8e8;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

/* Form Elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.4rem;
    color: #333;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ddd;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 3px rgba(67, 97, 238, 0.1);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-group label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-weight: normal;
}

.checkbox-group input[type="checkbox"] {
    width: 16px;
    height: 16px;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #eee;
}

.btn-primary {
    padding: 0.7rem 1.8rem;
    background: #4361ee;
    color: #fff;
    border: none;
    border-radius: 6px;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-primary:hover:not(:disabled) {
    background: #3651d4;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-outline {
    padding: 0.7rem 1.8rem;
    background: transparent;
    color: #4361ee;
    border: 1px solid #4361ee;
    border-radius: 6px;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-outline:hover {
    background: #f0f3ff;
}

.btn-secondary {
    padding: 0.5rem 1.2rem;
    background: #f8f9fa;
    color: #333;
    border: 1px solid #ddd;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
    margin-bottom: 1rem;
}

.btn-secondary:hover {
    background: #e9ecef;
}

.btn-danger-sm {
    padding: 0.3rem 0.8rem;
    background: #fff;
    color: #e63946;
    border: 1px solid #e63946;
    border-radius: 4px;
    font-size: 0.8rem;
    cursor: pointer;
}

.btn-danger-sm:hover {
    background: #fff5f5;
}

.btn-link {
    background: none;
    border: none;
    color: #4361ee;
    font-size: 0.9rem;
    cursor: pointer;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #3651d4;
}

.btn-submit {
    padding: 0.8rem 2.5rem;
    font-size: 1rem;
