+    box-sizing: border-box;
+}
+
+.form-group input:focus,
+.form-group textarea:focus {
+    outline: none;
+    border-color: #4361ee;
+    box-shadow: 0 0 0 3px rgba(67, 97, 238, 0.1);
+}
+
+.form-row {
+    display: grid;
+    grid-template-columns: 1fr 1fr;
+    gap: 1rem;
+}
+
+.checkbox-group label {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    font-weight: normal;
+}
+
+.checkbox-group input[type="checkbox"] {
+    width: 16px;
+    height: 16px;
+}
+
+/* Buttons */
+.step-buttons {
+    display: flex;
+    justify-content: space-between;
+    margin-top: 2rem;
+    padding-top: 1.5rem;
+    border-top: 1px solid #eee;
+}
+
+.btn-primary {
+    padding: 0.7rem 1.8rem;
+    background: #4361ee;
+    color: #fff;
+    border: none;
+    border-radius: 6px;
+    font-size: 0.95rem;
+    font-weight: 500;
+    cursor: pointer;
+    transition: background 0.2s;
+}
+
+.btn-primary:hover:not(:disabled) {
+    background: #3651d4;
+}
+
+.btn-primary:disabled {
+    opacity: 0.6;
+    cursor: not-allowed;
+}
+
+.btn-outline {
+    padding: 0.7rem 1.8rem;
+    background: transparent;
+    color: #4361ee;
+    border: 1px solid #4361ee;
+    border-radius: 6px;
+    font-size: 0.95rem;
+    font-weight: 500;
+    cursor: pointer;
+    transition: all 0.2s;
+}
+
+.btn-outline:hover {
+    background: #f0f3ff;
+}
+
+.btn-secondary {
+    padding: 0.5rem 1.2rem;
+    background: #f8f9fa;
+    color: #333;
+    border: 1px solid #ddd;
+    border-radius: 6px;
+    font-size: 0.9rem;
+    cursor: pointer;
+    margin-bottom: 1rem;
+}
+
+.btn-secondary:hover {
+    background: #e9ecef;
+}
+
+.btn-danger-sm {
+    padding: 0.3rem 0.8rem;
+    background: #fff;
+    color: #e63946;
+    border: 1px solid #e63946;
+    border-radius: 4px;
+    font-size: 0.8rem;
+    cursor: pointer;
+}
+
+.btn-danger-sm:hover {
+    background: #fff5f5;
+}
+
+.btn-link {
+    background: none;
+    border: none;
+    color: #4361ee;
+    font-size: 0.9rem;
+    cursor: pointer;
+    text-decoration: underline;
+    padding: 0;
+}
+
+.btn-link:hover {
+    color: #3651d4;
+}
+
+.btn-submit {
+    padding: 0.8rem 2.5rem;
+    font-size: 1rem;
+}
+
+/* Errors & Messages */
+.field-error {
+    color: #e63946;
+    font-size: 0.85rem;
+    margin-top: 0.3rem;
+    display: block;
+}
+
+.info-message {
+    color: #4361ee;
+    font-size: 0.9rem;
+    font-style: italic;
+}
+
+.hint {
+    color: #666;
+    font-size: 0.9rem;
+    margin-bottom: 1.5rem;
+}
+
+.char-count {
+    display: block;
+    text-align: right;
+    font-size: 0.85rem;
+    color: #666;
+    margin-top: 0.4rem;
+}
+
+.char-count.near-limit {
+    color: #e63946;
+    font-weight: 500;
+}
+
+/* Work Entry & Reference Forms */
+.work-entry-form,
+.reference-entry {
+    border: 1px solid #e8e8e8;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+    background: #fafbfc;
+}
+
+.entry-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 1rem;
+}
+
+.entry-header h4 {
+    margin: 0;
+    color: #333;
+}
+
+/* Review Step */
+.review-section {
+    border: 1px solid #e8e8e8;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+}
+
+.section-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+.section-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #1a1a2e;
+}
+
+.review-section dl {
+    display: grid;
+    grid-template-columns: 120px 1fr;
+    gap: 0.4rem 1rem;
+    margin: 0;
+}
+
+.review-section dt {
+    font-weight: 500;
+    color: #666;
+    font-size: 0.9rem;
+}
+
+.review-section dd {
+    margin: 0;
+    font-size: 0.9rem;
+}
+
+.review-work-entry,
+.review-reference {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #f0f0f0;
+}
+
+.review-work-entry:last-child,
+.review-reference:last-child {
+    border-bottom: none;
+}
+
+.date-range {
+    font-size: 0.85rem;
+    color: #666;
+}
+
+.entry-description {
+    font-size: 0.9rem;
+    color: #555;
+    margin: 0.3rem 0 0 0;
+}
+
+.cover-letter-preview {
+    white-space: pre-wrap;
+    font-size: 0.9rem;
+    color: #333;
+    line-height: 1.6;
+}
+
+/* Confirmation */
+.confirmation {
+    text-align: center;
+    padding: 3rem 2rem;
+    background: #fff;
+    border: 1px solid #e8e8e8;
+    border-radius: 8px;
+}
+
+.confirmation-icon {
+    width: 64px;
+    height: 64px;
+    border-radius: 50%;
+    background: #2ec4b6;
+    color: #fff;
+    font-size: 2rem;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    margin: 0 auto 1.5rem;
+}
+
+.confirmation h2 {
+    color: #2ec4b6;
+    margin-bottom: 1rem;
+}
+
+.application-id {
+    font-size: 1.5rem;
+    font-weight: 700;
+    color: #4361ee;
+}
+

