@namespace sv_6d3535725b4f400e81fef8180acb677d.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn-danger-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="OnCompanyChanged" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="OnTitleChanged" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="OnStartDateChanged" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? "")"
                   disabled="@_isCurrent" @onchange="OnEndDateChanged" />
        </div>
    </div>

    <div class="form-group checkbox-group">
        <label>
            <input type="checkbox" checked="@_isCurrent" @onchange="ToggleCurrent" />
            I currently work here
        </label>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description" @onchange="OnDescriptionChanged"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool _isCurrent;

    protected override void OnParametersSet()
    {
        _isCurrent = Entry.EndDate is null && Entry.StartDate != default;
    }

    private void OnCompanyChanged(ChangeEventArgs e)
    {
        Entry.Company = (string?)e.Value ?? "";
        NotifyChanged();
    }

    private void OnTitleChanged(ChangeEventArgs e)
    {
        Entry.Title = (string?)e.Value ?? "";
        NotifyChanged();
    }

    private void OnStartDateChanged(ChangeEventArgs e)
    {
        if (DateTime.TryParse((string?)e.Value, out var date))
            Entry.StartDate = date;
        NotifyChanged();
    }

    private void OnEndDateChanged(ChangeEventArgs e)
    {
        var val = (string?)e.Value;
        Entry.EndDate = string.IsNullOrEmpty(val) ? null : DateTime.TryParse(val, out var d) ? d : null;
        NotifyChanged();
    }

    private void OnDescriptionChanged(ChangeEventArgs e)
    {
        Entry.Description = (string?)e.Value ?? "";
        NotifyChanged();
    }

    private void ToggleCurrent(ChangeEventArgs e)
    {
        _isCurrent = (bool)(e.Value ?? false);
        if (_isCurrent)
        {
            Entry.EndDate = null;
            NotifyChanged();
        }
    }

    private async void NotifyChanged()
    {
        await OnEntryChanged.InvokeAsync(Entry);
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public string Description { get; set; } = "";
    }
}

